package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.MergedIntoVO;

@RequiredArgsConstructor
public class MergedIntoValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<MergedIntoVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getMergedInto() {
    return value.flatMap(MergedIntoVO::getMergedInto);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<MergedIntoVO> getMergedIntoValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param mergedInto
   * @return
   */
  public T mergedInto(MergedIntoVO mergedInto) {
    this.value = Optional.of(mergedInto);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param mergedInto
   * @return
   */
  public T mergedInto(Optional<MergedIntoVO> mergedInto) {
    this.value = mergedInto;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param mergedInto
   * @return
   */
  public T mergedInto(String mergedInto) {
    this.value = Optional.of(MergedIntoVO.from(mergedInto));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T mergedIntoNull() {
    this.value = Optional.of(MergedIntoVO.nullValue());
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public MergedIntoVO readMergedInto(final Optional<ObservedIssue> original,
      final ConstraintFailList fails) {
    return value
        .orElse(original.map(ObservedIssue::getMergedIntoValue).orElseGet(MergedIntoVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetMergedInto() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetMergedIntoIfMatches(final String field) {
    if ("mergedInto".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
